import { forEachDocumentPosition } from './documentPositions.js';
// RFC 9110 field names are tokens: letters, digits and these symbols, nothing else
const TOKEN_SYMBOLS = new Set("!#$%&'*+-.^_`|~");
const isTokenChar = (char) => (char >= 'a' && char <= 'z') ||
    (char >= 'A' && char <= 'Z') ||
    (char >= '0' && char <= '9') ||
    TOKEN_SYMBOLS.has(char);
const isValidHeaderName = (name) => typeof name === 'string' && name.length > 0 && [...name].every(isTokenChar);
export const validateHeaderNames = (document) => {
    const errors = [];
    const report = (path, name) => errors.push({ path, message: `Header name ${name} is not a valid HTTP field name` });
    forEachDocumentPosition(document, {
        onParameter: (path, parameter) => {
            if (parameter.in === 'header' && typeof parameter.name === 'string') {
                if (!isValidHeaderName(parameter.name))
                    report(`${path}/name`, parameter.name);
            }
        },
        onHeaderName: (path, name) => {
            if (!isValidHeaderName(name))
                report(path, name);
        },
    });
    return errors;
};
